import {SHINY_PALETTES} from './shiny-palettes.js?v=0.90.40';
export const SHINY_DENOMINATOR=4096,EGG_SHINY_DENOMINATOR=2048;
export function rollShiny(random=Math.random,{bred=false}={}){const roll=random();return Number.isFinite(roll)&&roll>=0&&roll<1/(bred?EGG_SHINY_DENOMINATOR:SHINY_DENOMINATOR);}
export function assignShiny(unit,{random=Math.random}={}){if(typeof unit.shiny!=='boolean')unit.shiny=rollShiny(random);return unit;}
export function shinySummaryHTML(unit){return unit?.shiny===true?'<p class="shiny-badge"><b>✦ Shiny Abyssal</b> · Rare family palette</p>':'';}
// Recolour in perceptual lightness/chroma space. Outlines, whites, shading and alpha
// remain structural parts of the original drawing, rather than becoming inverted noise.
const linear=Float64Array.from({length:256},(_,i)=>{const v=i/255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;});
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const smooth=(a,b,v)=>{const t=clamp((v-a)/(b-a));return t*t*(3-2*t);};
export function rgbToOKLab(r,g,b){r=linear[r];g=linear[g];b=linear[b];const l=Math.cbrt(.4122214708*r+.5363325363*g+.0514459929*b),m=Math.cbrt(.2119034982*r+.6806995451*g+.1073969566*b),s=Math.cbrt(.0883024619*r+.2817188376*g+.6299787005*b);return [.2104542553*l+.793617785*m-.0040720468*s,1.9779984951*l-2.428592205*m+.4505937099*s,.0259040371*l+.7827717662*m-.808675766*s];}
function labRGB(L,a,b){const l=(L+.3963377774*a+.2158037573*b)**3,m=(L-.1055613458*a-.0638541728*b)**3,s=(L-.0894841775*a-1.291485548*b)**3;return [4.0767416621*l-3.3077115913*m+.2309699292*s,-1.2684380046*l+2.6097574011*m-.3413193965*s,-.0041960863*l-.7034186147*m+1.707614701*s];}
const inGamut=rgb=>rgb.every(v=>v>=-.000001&&v<=1.000001);
const encode=v=>Math.round(255*(v<=.0031308?12.92*clamp(v):1.055*clamp(v)**(1/2.4)-.055));
export const DEFAULT_SHINY_PALETTE={family:'fallback',sourceHue:270,targetHue:165,chroma:.96,neutralTint:0};
export function shinyPalette(subject){const id=typeof subject==='string'?subject:subject?.species?.id??subject?.id;return SHINY_PALETTES[id]||SHINY_PALETTES[String(id||'').split('-')[0]]||DEFAULT_SHINY_PALETTE;}
export function recolourShiny(pixels,profile=DEFAULT_SHINY_PALETTE){const memo=new Map(),rad=Math.PI/180;for(let i=0;i<pixels.length;i+=4){if(!pixels[i+3])continue;const key=(pixels[i]<<16)|(pixels[i+1]<<8)|pixels[i+2];let value=memo.get(key);if(value===undefined){const [L,a,b]=rgbToOKLab(pixels[i],pixels[i+1],pixels[i+2]),C=Math.hypot(a,b),protect=smooth(.006,.04,C)*smooth(.07,.18,L)*(1-smooth(.93,.995,L)),tint=(profile.neutralTint||0)*(1-smooth(.012,.045,C))*smooth(.15,.38,L)*(1-smooth(.82,.98,L));if(protect===0&&tint===0){value=key;}else{const h=(Math.atan2(b,a)/rad+360)%360,offset=(h-profile.sourceHue+360)%360,warp=offset<120?offset*110/120:offset<240?110+(offset-120)*125/120:235+(offset-240)*125/120,target=(profile.targetHue+warp)*rad,ta=C*(profile.chroma??1)*Math.cos(target),tb=C*(profile.chroma??1)*Math.sin(target);let oa=a+(ta-a)*protect+tint*Math.cos(profile.targetHue*rad),ob=b+(tb-b)*protect+tint*Math.sin(profile.targetHue*rad),rgb=labRGB(L,oa,ob);if(!inGamut(rgb)){let low=0,high=1;for(let n=0;n<9;n++){const scale=(low+high)/2;if(inGamut(labRGB(L,oa*scale,ob*scale)))low=scale;else high=scale;}rgb=labRGB(L,oa*low,ob*low);}value=(encode(rgb[0])<<16)|(encode(rgb[1])<<8)|encode(rgb[2]);}memo.set(key,value);}pixels[i]=value>>>16;pixels[i+1]=(value>>>8)&255;pixels[i+2]=value&255;}return pixels;}
// Retain the old export for callers importing historical helpers; its rendering is clean now.
export const oppositeColours=pixels=>recolourShiny(pixels);
const transformed=new WeakMap();
export function shinyCanvas(image,subject){if(!image.complete||!image.naturalWidth)return null;const profile=shinyPalette(subject);let variants=transformed.get(image);if(!variants){variants=new Map();transformed.set(image,variants);}if(variants.has(profile))return variants.get(profile);const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);recolourShiny(pixels.data,profile);ctx.putImageData(pixels,0,0);canvas.complete=true;canvas.naturalWidth=canvas.width;canvas.naturalHeight=canvas.height;variants.set(profile,canvas);return canvas;}
